package com.cms.service;
import com.cms.dto.*; import com.cms.entity.Category; import com.cms.exception.BusinessException; import com.cms.repository.CategoryRepository; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @RequiredArgsConstructor public class CategoryService {private final CategoryRepository repo;private final CategoryMapper mapper; @Transactional public CategoryResponse create(CategoryRequest r){if(repo.findByNameIgnoreCase(r.name()).isPresent())throw new BusinessException("Category name already exists");return mapper.toResponse(repo.save(Category.builder().name(r.name().trim()).description(r.description()).build()));} @Transactional(readOnly=true) public List<CategoryResponse> all(){return repo.findAll().stream().map(mapper::toResponse).toList();}}
